<template><view class="page"><view class="bar"><button size="mini" @click="load" :disabled="busy">刷新状态</button><button size="mini" @click="go('/pages/index/index')">返回首页</button><button size="mini" @click="go('/pages/assistant/assistant')">听见助手</button></view><text class="notice">申请需先核对再确认，10 分钟内有效。审核通过也不代表退款到账。</text><text class="error">{{error}}</text><button v-if="!store.token" @click="go('/pages/login/login')">请先登录</button>
<view class="card"><text class="heading">本地交易演示</text><text class="notice">仅模拟下单、支付和退款，不扣款、不解锁付费内容。订单 15 分钟未支付自动取消。</text><view v-for="p in products" :key="p.code"><text class="facts">{{p.title}} · ¥{{p.amount}}</text><button size="mini" :disabled="busy||!store.token" @click="buy(p)">核对并创建本地订单</button></view></view>
<text class="heading">售后申请 · 共 {{requestTotal}} 条</text><view class="card" v-for="r in requests" :key="r.id"><text class="badge">{{r.statusLabel}}</text><text class="title">{{r.title}}</text><text class="facts">订单号：{{r.orderNo}}
订单金额：¥{{r.amount}}
原因：{{r.reason}}
申请编号：{{r.id}}</text><text class="notice" v-if="r.reviewNote">审核意见：{{r.reviewNote}} · {{time(r.reviewedAt)}}</text><text class="hint" v-if="r.status==='DRAFT'">请核对订单、金额和原因，确认有效至 {{time(r.expiresAt)}}。</text><view class="bar"><button size="mini" :disabled="busy" v-if="r.status==='DRAFT'" @click="confirm(r.id)">确认登记，等待审核</button><button size="mini" class="secondary" :disabled="busy" v-if="['DRAFT','SUBMITTED'].includes(r.status)" @click="withdraw(r.id)">{{r.status==='DRAFT'?'放弃草稿':'撤回申请'}}</button></view></view><text class="hint" v-if="!requests.length">当前页没有售后申请。</text><view class="bar"><button size="mini" :disabled="requestPage===1||busy" @click="change('request',-1)">上一页申请</button><text>{{requestPage}} / {{Math.max(1,Math.ceil(requestTotal/10))}}</text><button size="mini" :disabled="requestPage*10>=requestTotal||busy" @click="change('request',1)">下一页申请</button></view>
<text class="heading">我的订单 · 共 {{orderTotal}} 条</text><view v-for="order in orders" :key="order.id" class="card"><text class="badge">{{order.statusLabel}}</text><text class="title">{{order.title}}</text><text class="facts">订单号：{{order.orderNo}}
订单金额：¥{{order.amount}}</text><view v-if="localOrders[order.id]"><text class="notice">本地模拟渠道 · {{localOrders[order.id].paymentStatus}}<text v-if="order.status==='0901'"> · 支付截止 {{time(localOrders[order.id].expiresAt)}}</text></text><view class="bar" v-if="order.status==='0901'"><button size="mini" :disabled="busy" @click="pay(order,'SUCCESS')">模拟支付成功</button><button size="mini" :disabled="busy" class="secondary" @click="pay(order,'FAILED')">模拟支付失败</button><button size="mini" :disabled="busy" class="secondary" @click="cancel(order.id)">取消未支付订单</button></view><button size="mini" class="secondary" :disabled="busy" @click="showEvents(order.id)">交易操作记录</button><text class="facts" v-if="eventText[order.id]">{{eventText[order.id]}}</text></view><button size="mini" :disabled="busy" v-if="order.status==='0902'" @click="selected=order.id">申请售后</button><view v-if="selected===order.id"><textarea v-model="reason" maxlength="300" placeholder="填写 5 至 300 字售后原因"/><button size="mini" :disabled="busy" @click="prepare(order.id)">下一步：核对申请</button></view></view><text class="hint" v-if="!orders.length">当前页没有订单。</text><view class="bar"><button size="mini" :disabled="orderPage===1||busy" @click="change('order',-1)">上一页订单</button><text>{{orderPage}} / {{Math.max(1,Math.ceil(orderTotal/10))}}</text><button size="mini" :disabled="orderPage*10>=orderTotal||busy" @click="change('order',1)">下一页订单</button></view></view></template>
<script setup lang="ts">
import {ref} from 'vue';import {onShow} from '@dcloudio/uni-app';import {useUserStore} from '../../stores/user';import {listeningRequest} from '../../api/listening';
const store=useUserStore(),orders=ref<any[]>([]),requests=ref<any[]>([]),orderTotal=ref(0),requestTotal=ref(0),orderPage=ref(1),requestPage=ref(1),busy=ref(false),error=ref(''),selected=ref(''),reason=ref('');
const products=ref<any[]>([]),localOrders=ref<Record<string,any>>({}),eventText=ref<Record<string,string>>({});
function go(url:string){uni.navigateTo({url})}function time(value:string){return new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}
async function read(){const [o,r,p]=await Promise.all([listeningRequest('/api/business/orders/page?page='+orderPage.value),listeningRequest('/api/business/after-sales/page?page='+requestPage.value),listeningRequest('/api/business/local/products')]);orders.value=o.records;orderTotal.value=o.total;requests.value=r.records;requestTotal.value=r.total;products.value=p;localOrders.value={};await Promise.all(o.records.filter((v:any)=>v.title.includes('本地交易演示套餐')).map(async(v:any)=>{localOrders.value[v.id]=await listeningRequest('/api/business/local/orders/'+v.id)}))}
async function run(action:()=>Promise<any>){if(busy.value||!store.token)return;busy.value=true;error.value='';try{await action()}catch(e:any){error.value=e.message}finally{busy.value=false}}
function load(){return run(read)}function change(type:string,n:number){if(type==='order')orderPage.value+=n;else requestPage.value+=n;load()}
function prepare(orderId:string){run(async()=>{await listeningRequest('/api/business/after-sales/prepare','POST',{orderId,reason:reason.value.trim()});requestPage.value=1;selected.value='';reason.value='';await read();uni.pageScrollTo({scrollTop:0})})}
function confirm(id:string){run(async()=>{await listeningRequest('/api/business/after-sales/'+id+'/confirm','POST',{confirmed:true});await read()})}
function withdraw(id:string){run(async()=>{await listeningRequest('/api/business/after-sales/'+id+'/withdraw','POST');await read()})}
function ask(content:string):Promise<boolean>{return new Promise(resolve=>uni.showModal({title:'确认本地模拟操作',content,success:r=>resolve(r.confirm),fail:()=>resolve(false)}))}
function buy(p:any){run(async()=>{if(!await ask(p.title+'，金额 ¥'+p.amount+'。仅创建演示订单，无真实扣款。'))return;const storageKey='checkout-key-'+store.user?.id;let key=uni.getStorageSync(storageKey);if(!key){key=Date.now().toString(16)+Math.random().toString(16).slice(2);uni.setStorageSync(storageKey,key)}await listeningRequest('/api/business/local/checkout','POST',{product:p.code,idempotencyKey:key,confirmed:true});uni.removeStorageSync(storageKey);orderPage.value=1;await read()})}
function pay(o:any,outcome:string){run(async()=>{if(!await ask('订单 '+o.orderNo+'，金额 ¥'+o.amount+'。模拟'+(outcome==='SUCCESS'?'支付成功':'支付失败')+'，不涉及真实资金。'))return;await listeningRequest('/api/business/local/orders/'+o.id+'/simulate','POST',{outcome,confirmed:true});await read()})}
function cancel(id:string){run(async()=>{if(!await ask('取消这个未支付的本地订单？'))return;await listeningRequest('/api/business/local/orders/'+id+'/cancel','POST');await read()})}
function showEvents(id:string){run(async()=>{const rows=await listeningRequest('/api/business/local/orders/'+id+'/events');eventText.value[id]=rows.map((e:any)=>time(e.create_time)+' · '+e.event_type).join('\n')})}
onShow(load);
</script><style scoped>.page{padding:30rpx;background:#f3f5ef;min-height:100vh}.bar{display:flex;gap:12rpx;flex-wrap:wrap;align-items:center;margin:24rpx 0}.heading{display:block;font-size:32rpx;font-weight:bold;margin:32rpx 0}.card{padding:28rpx;background:white;border-radius:18rpx;margin:24rpx 0}.badge{background:#edf3e8;color:#456451;padding:8rpx 16rpx;border-radius:20rpx;font-size:24rpx;display:inline-block}.title{display:block;font-size:30rpx;font-weight:bold;margin:20rpx 0}.facts{display:block;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.9;font-size:26rpx}.hint{display:block;font-size:24rpx;color:#789183;line-height:1.8;margin:20rpx 0}.notice{display:block;padding:20rpx;background:#edf3e8;font-size:24rpx;line-height:1.8;border-radius:12rpx;margin:20rpx 0}button{background:#244f45;color:white;margin:0}.secondary{background:#e8efe6;color:#244f45}textarea{border:1px solid #dce4d5;border-radius:12rpx;padding:20rpx;width:100%;box-sizing:border-box;margin:20rpx 0}.error{color:#a04836;display:block}</style>
